const qs_input_t *in = &qs_input;
const qs_config_t *cfg = &qs_config;
qs_state_t *st = &qs_state;
qs_output_t *out = &qs_output;
adcs_quat_t qc, qt, qrel;
adcs_vec3_t axis;
double nrm, angle, w, s, braking, rate, target, delta, step, applied;

/* default identity output */
out->command_q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
out->slew_axis = (adcs_vec3_t){0.0, 0.0, 0.0};
out->reversal_reset = 0;
out->settled = st->settled;
out->mode = st->mode;
out->error_angle_rad = 0.0;
out->applied_step_rad = 0.0;
out->commanded_rate_rad_cycle = st->commanded_rate_rad_cycle;
out->braking_rate_rad_cycle = 0.0;

/* 1. validate */
if (in == NULL || cfg == NULL || st == NULL || out == NULL) {
    st->mode = QS_FAULT; st->commanded_rate_rad_cycle = 0.0; st->axis_valid = 0; st->settled = 0;
    out->mode = QS_FAULT; out->commanded_rate_rad_cycle = 0.0; out->settled = 0;
    return;
}
if (!in->enable) {
    st->mode = QS_HOLD; st->commanded_rate_rad_cycle = 0.0; st->axis_valid = 0;
    st->settled = 0;
    out->mode = QS_HOLD; out->commanded_rate_rad_cycle = 0.0; out->settled = 0;
    out->command_q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    return;
}
if (in->current_q_bi == NULL || in->target_q_bi == NULL) {
    st->mode = QS_FAULT; st->commanded_rate_rad_cycle = 0.0; st->axis_valid = 0; st->settled = 0;
    out->mode = QS_FAULT; out->commanded_rate_rad_cycle = 0.0; out->settled = 0;
    return;
}
if (!isfinite(cfg->max_rate_rad_cycle) || !isfinite(cfg->max_accel_rad_cycle2) ||
    !isfinite(cfg->settle_angle_rad) || !isfinite(cfg->settle_rate_rad_cycle) ||
    cfg->max_rate_rad_cycle <= 0.0 || cfg->max_rate_rad_cycle > ADCS_PI ||
    cfg->max_accel_rad_cycle2 <= 0.0 ||
    cfg->settle_rate_rad_cycle < 0.0 || cfg->settle_rate_rad_cycle > cfg->max_rate_rad_cycle ||
    cfg->settle_angle_rad < 0.0 || cfg->settle_angle_rad > cfg->max_rate_rad_cycle ||
    cfg->settle_cycles < 1u || cfg->settle_cycles > 20u) {
    st->mode = QS_FAULT; st->commanded_rate_rad_cycle = 0.0; st->axis_valid = 0; st->settled = 0;
    out->mode = QS_FAULT; out->commanded_rate_rad_cycle = 0.0; out->settled = 0;
    return;
}
if (!isfinite(in->current_q_bi->w) || !isfinite(in->current_q_bi->x) ||
    !isfinite(in->current_q_bi->y) || !isfinite(in->current_q_bi->z) ||
    !isfinite(in->target_q_bi->w) || !isfinite(in->target_q_bi->x) ||
    !isfinite(in->target_q_bi->y) || !isfinite(in->target_q_bi->z)) {
    st->mode = QS_FAULT; st->commanded_rate_rad_cycle = 0.0; st->axis_valid = 0; st->settled = 0;
    out->mode = QS_FAULT; out->commanded_rate_rad_cycle = 0.0; out->settled = 0;
    return;
}
if (adcs_quat_normalize(in->current_q_bi, &qc) != ADCS_OK ||
    adcs_quat_normalize(in->target_q_bi, &qt) != ADCS_OK) {
    st->mode = QS_FAULT; st->commanded_rate_rad_cycle = 0.0; st->axis_valid = 0; st->settled = 0;
    out->mode = QS_FAULT; out->commanded_rate_rad_cycle = 0.0; out->settled = 0;
    return;
}

/* 2. relative quaternion, shortest sign */
{
    adcs_quat_t qcc = adcs_quat_conjugate(&qc);
    qrel = adcs_quat_multiply(&qt, &qcc);
    if (qrel.w < 0.0) {
        qrel.w = -qrel.w; qrel.x = -qrel.x; qrel.y = -qrel.y; qrel.z = -qrel.z;
    }
}

/* 3. principal angle and axis */
w = qrel.w;
if (w > 1.0) w = 1.0;
if (w < -1.0) w = -1.0;
angle = 2.0 * acos(w);
axis = (adcs_vec3_t){qrel.x, qrel.y, qrel.z};
nrm = adcs_vec3_norm(&axis);
if (nrm > ADCS_EPS_NORM) {
    axis = adcs_vec3_scale(&axis, 1.0 / nrm);
    /* 4. braking envelope */
    braking = sqrt(2.0 * cfg->max_accel_rad_cycle2 * angle);

    /* 5. reversal reset */
    if (st->axis_valid) {
        double d = adcs_vec3_dot(&axis, &st->previous_axis);
        if (d < 0.0) {
            st->commanded_rate_rad_cycle = 0.0;
            out->reversal_reset = 1;
        }
    }
    st->previous_axis = axis;
    st->axis_valid = 1;
    out->slew_axis = axis;
} else {
    braking = sqrt(2.0 * cfg->max_accel_rad_cycle2 * angle);
    out->slew_axis = st->axis_valid ? st->previous_axis : (adcs_vec3_t){0.0, 0.0, 0.0};
}
out->braking_rate_rad_cycle = braking;

/* 6. rate approach toward min(max_rate, braking), limited by max_accel */
target = (braking < cfg->max_rate_rad_cycle) ? braking : cfg->max_rate_rad_cycle;
rate = st->commanded_rate_rad_cycle;
s = rate;
delta = target - rate;
step = cfg->max_accel_rad_cycle2;
if (delta > step) delta = step;
if (delta < -step) delta = -step;
rate = rate + delta;
/* never overshoot target angle */
if (rate > angle) rate = angle;
if (rate < 0.0) rate = 0.0;

/* 7. mode determination */
if (rate > s + FLT64_ZERO) {
    st->mode = QS_ACCEL;
} else if (rate < s - FLT64_ZERO) {
    st->mode = QS_DECEL;
} else if (rate >= cfg->max_rate_rad_cycle - FLT64_ZERO && angle > rate) {
    st->mode = QS_CRUISE;
}

/* 8. settle window */
if (angle <= cfg->settle_angle_rad && rate <= cfg->settle_rate_rad_cycle) {
    st->settled = st->settled + 1u;
    st->mode = QS_SETTLE;
    if (st->settled >= cfg->settle_cycles) {
        st->mode = QS_HOLD;
        rate = 0.0;
    }
} else {
    st->settled = 0;
}

st->commanded_rate_rad_cycle = rate;
out->commanded_rate_rad_cycle = rate;

/* 9. applied step and command quaternion */
applied = (rate < angle) ? rate : angle;
out->applied_step_rad = applied;
out->error_angle_rad = angle;
out->settled = st->settled;
out->mode = st->mode;
{
    adcs_quat_t dq;
    double half, sh;
    if (applied > FLT64_ZERO && nrm > ADCS_EPS_NORM) {
        half = 0.5 * applied;
        sh = sin(half);
        dq = (adcs_quat_t){cos(half), sh * axis.x, sh * axis.y, sh * axis.z};
        out->command_q_bi = adcs_quat_multiply(&dq, &qc);
    } else {
        out->command_q_bi = qc;
    }
}
return;

