    if (n >= qs_config.settle_cycles) {
        qs_state.settled = qs_config.settle_cycles;
        qs_state.mode = QS_HOLD;
    } else {
        qs_state.settled = n;
        qs_state.mode = QS_SETTLE;
    }
} else {
    qs_state.settled = 0U;
}
if (qs_state.mode == QS_HOLD) {
    qs_state.commanded_rate_rad_cycle = 0.0;
    rate = 0.0;
    applied = 0.0;
}

/* 子过程K：保存最近非零轴 */
if (have_axis) {
    qs_state.previous_axis = axis;
    qs_state.axis_valid = 1;
}

/* 子过程L：输出填充 */
qs_output.mode = qs_state.mode;
qs_output.settled = qs_state.settled;
qs_output.error_angle_rad = angle;
qs_output.applied_step_rad = applied;
qs_output.commanded_rate_rad_cycle = qs_state.commanded_rate_rad_cycle;
qs_output.braking_rate_rad_cycle = envelope;
qs_output.reversal_reset = reversal;
qs_output.slew_axis = axis;

if (applied > 0.0 && have_axis) {
    double half = 0.5 * applied;
    double s = sin(half);
    adcs_quat_t dq;
    dq.w = cos(half);
    dq.x = s * axis.x;
    dq.y = s * axis.y;
    dq.z = s * axis.z;
    q_cmd = adcs_quat_multiply(&dq, &q_cur_n);
    (void)adcs_quat_normalize(&q_cmd, &q_cmd);
} else {
    q_cmd = q_cur_n;
}
qs_output.command_q_bi = q_cmd;
